global.set('system_ready', false);
global.set('roi_config', null);
flow.set('device_id', 'unknown');
flow.set('door_label', '?');
flow.set('start_time', Date.now());
flow.set('config_error', false);
flow.set('roi_error', false);
flow.set('last_gate_status', 'booting');
flow.set('last_track_status', {
