    let final = null;
    if (cfg && Array.isArray(cfg.polygon) && cfg.polygon.length >= 3
        && typeof cfg.count_edge_index === 'number'
        && cfg.count_edge_index >= 0 && cfg.count_edge_index < cfg.polygon.length) {
        final = {
            polygon: cfg.polygon,
            count_edge_index: cfg.count_edge_index,
            entry_area: cfg.entry_area === 'outside' ? 'outside' : 'inside',
            masks: Array.isArray(cfg.masks) ? cfg.masks : []
