    } else if (cfg && Array.isArray(cfg.rect) && cfg.rect.length === 4 && cfg.count_edge) {
        // Legacy rect config: auto-migrate to a 4-pt polygon
        const validEdges = ['top', 'bottom', 'left', 'right'];
        if (validEdges.indexOf(cfg.count_edge) < 0) {
            node.warn('Invalid count_edge: ' + cfg.count_edge);
            node.status({ fill: 'red', shape: 'ring', text: 'bad count_edge' });
            return null;
        }
        const x1 = cfg.rect[0], y1 = cfg.rect[1], x2 = cfg.rect[2], y2 = cfg.rect[3];
        const polygon = [[x1,y1],[x2,y1],[x2,y2],[x1,y2]];
        const edgeMap = { top: 0, right: 1, bottom: 2, left: 3 };
        const idx = edgeMap[cfg.count_edge];
        final = {
            polygon: polygon,
            count_edge_index: idx,
