} catch(e) {
    node.warn('ROI parse error: ' + e.message);
    node.status({ fill: 'red', shape: 'ring', text: 'parse error' });
}
return null;

const errSource = msg.error ? msg.error.source : {};
const errMsg = msg.error ? msg.error.message : 'unknown';

if (errSource && errSource.id === 'prod_load_cfg') {
    const os = require('os');
    let fallbackId = os.hostname() || 'cam_' + Date.now().toString(36).slice(-4);
    fallbackId = fallbackId.replace(/[^a-zA-Z0-9_-]/g, '_');
