    flow.set('config_error', true);
    node.warn('Config file error: ' + errMsg + ' - using fallback device_id: ' + fallbackId);
    node.status({ fill: 'yellow', shape: 'ring', text: 'cfg err: ' + fallbackId });
} else if (errSource && errSource.id === 'prod_load_roi') {
    flow.set('roi_error', true);
    node.warn('ROI file error: ' + errMsg + ' - counting disabled until ROI is configured');
    node.status({ fill: 'red', shape: 'ring', text: 'NO ROI - counting disabled' });
}
return null;

if (!global.get('system_ready')) {
    flow.set('last_gate_status', 'No ROI');
    node.status({ fill: 'grey', shape: 'ring', text: 'No ROI' });
    return null;
}
const devId = flow.get('device_id');
if (!devId || devId === 'unknown') {
    flow.set('last_gate_status', 'No device ID');
    node.status({ fill: 'yellow', shape: 'ring', text: 'No device ID' });
    return null;
}
flow.set('last_gate_status', 'Active');
node.status({ fill: 'green', shape: 'dot', text: 'Active' });
return msg;

if (!msg.payload) {
    flow.set('last_track_status', { note: 'no_payload', ts: Date.now() });
    return null;
}
const data = msg.payload.data || msg.payload;
if (!data) {
    flow.set('last_track_status', { note: 'no_data', ts: Date.now() });
    return null;
}
const boxes = data.boxes || [];
const labels = data.labels || [];
const cfg = global.get('roi_config');
if (!cfg || !Array.isArray(cfg.polygon) || cfg.polygon.length < 3
    || typeof cfg.count_edge_index !== 'number'
    || cfg.count_edge_index < 0 || cfg.count_edge_index >= cfg.polygon.length) {
    flow.set('last_track_status', { note: 'bad_roi', boxes: Array.isArray(boxes) ? boxes.length : 0, ts: Date.now() });
    return null;
}

// SORT-lite tracker (IoU + EMA + dwell-time + perp-velocity + region cooldown).
// Same tunable knobs and algorithm as maintenance V2 flow.
const TUNE = {
    iouMatchThreshold: 0.10,
    distMatchPx: 200,
    posSmoothingAlpha: 0.4,
    trackConfirmHits: 3,
    trackMaxAge: 30,
    stateWindowFrames: 5,
    minStateDwellFrames: 8,
    perpVelocityMinPx: 8,
    perpVelocityWindowFrames: 5,
    regionCooldownPx: 60,
    regionCooldownFrames: 30,
    minDetConfidence: 0.45,
    inferenceLookbackFrames: 60,
    inferenceParallelMaxPx: 80
};

const poly = cfg.polygon;
const N = poly.length;
const edgeStart = { x: poly[cfg.count_edge_index][0], y: poly[cfg.count_edge_index][1] };
const edgeEnd = { x: poly[(cfg.count_edge_index+1) % N][0], y: poly[(cfg.count_edge_index+1) % N][1] };
const eDx = edgeEnd.x - edgeStart.x, eDy = edgeEnd.y - edgeStart.y;
const eLen = Math.hypot(eDx, eDy) || 1;
const lineDir = { x: eDx / eLen, y: eDy / eLen };
const nrm = { x: -eDy / eLen, y: eDx / eLen };
// Inward normal points INTO polygon. Determined via centroid sign test.
let _cx = 0, _cy = 0;
for (const _p of poly) { _cx += _p[0]; _cy += _p[1]; }
_cx /= N; _cy /= N;
const _emx = (edgeStart.x + edgeEnd.x) / 2;
const _emy = (edgeStart.y + edgeEnd.y) / 2;
const _inwardSign = ((_cx - _emx) * nrm.x + (_cy - _emy) * nrm.y) > 0 ? 1 : -1;
const inwardNormal = { x: nrm.x * _inwardSign, y: nrm.y * _inwardSign };
const masks = cfg.masks || [];
const entryArea = cfg.entry_area === 'outside' ? 'outside' : 'inside';
const eventForArea = (inside) => {
    const entryIsInside = entryArea !== 'outside';
    return inside === entryIsInside ? 'ENTRY' : 'EXIT';
};
const now = Date.now();
const frame = (context.get('frame') || 0) + 1;
context.set('frame', frame);

// Presence trail: every detection's foot point + inside flag for crossing inference.
let presenceTrail = (context.get('presenceTrail') || []).filter(e => frame - e.frame < TUNE.inferenceLookbackFrames);

function inPoly(pt, p) {
    let inside = false;
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
        const xi = p[i][0], yi = p[i][1];
        const xj = p[j][0], yj = p[j][1];
        if (((yi > pt.y) !== (yj > pt.y)) && (pt.x < (xj - xi) * (pt.y - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
}
function iou(a, b) {
    const ax1 = a.x - a.w/2, ay1 = a.y - a.h/2, ax2 = a.x + a.w/2, ay2 = a.y + a.h/2;
    const bx1 = b.x - b.w/2, by1 = b.y - b.h/2, bx2 = b.x + b.w/2, by2 = b.y + b.h/2;
    const ix1 = Math.max(ax1, bx1), iy1 = Math.max(ay1, by1);
    const ix2 = Math.min(ax2, bx2), iy2 = Math.min(ay2, by2);
    const iw = Math.max(0, ix2 - ix1), ih = Math.max(0, iy2 - iy1);
    const inter = iw * ih;
    const aArea = Math.max(1, a.w * a.h), bArea = Math.max(1, b.w * b.h);
    return inter / (aArea + bArea - inter + 1e-9);
}

// 1. Extract person detections (filter by class, score, masks).
const dets = [];
if (Array.isArray(boxes)) {
    for (const b of boxes) {
        if (!Array.isArray(b) || b.length < 4) continue;
        const cx = Number(b[0]), cy = Number(b[1]), bw = Number(b[2]), bh = Number(b[3]);
        if (![cx, cy, bw, bh].every(Number.isFinite)) continue;

        let score = Number(b[4]);
        let classId = Number(b[5]);

        // Some model payloads are [x,y,w,h,class,score] instead of [x,y,w,h,score,class].
        if (!Number.isInteger(classId) && Number.isInteger(Number(b[4]))) {
            classId = Number(b[4]);
            score = Number(b[5]);
        }
        if (!Number.isFinite(score)) score = 1.0;
        if (score < TUNE.minDetConfidence) continue;

        const labelList = Array.isArray(labels) && labels.length ? labels : ['person'];
        let cls = String(labelList[classId] || '').toLowerCase();
        if (!cls && classId === 0) cls = 'person';
        if (cls !== 'person') continue;

        const fx = cx, fy = cy + bh / 2;
        let masked = false;
        for (const m of masks) {
            if (Array.isArray(m) && m.length >= 3 && inPoly({ x: fx, y: fy }, m)) { masked = true; break; }
        }
        if (masked) continue;
        dets.push({
            foot: { x: fx, y: fy },
            box: { x: cx, y: cy, w: bw, h: bh },
            score
        });
    }
}
// Append every accepted detection to the presence trail (for crossing inference).
for (const _d of dets) {
    presenceTrail.push({
        x: _d.foot.x, y: _d.foot.y, frame,
        inside: inPoly({ x: _d.foot.x, y: _d.foot.y }, poly)
    });
}

// 2. IoU-based association (greedy by descending IoU).
let tracks = context.get('tracks') || [];
const pairs = [];
for (let ti = 0; ti < tracks.length; ti++) {
    for (let di = 0; di < dets.length; di++) {
        const v = iou(tracks[ti].box, dets[di].box);
        if (v >= TUNE.iouMatchThreshold) pairs.push({ ti, di, score: v });
    }
}
pairs.sort((a, b) => b.score - a.score);
const usedT = new Set(), usedD = new Set();
const matches = [];
for (const p of pairs) {
    if (usedT.has(p.ti) || usedD.has(p.di)) continue;
    usedT.add(p.ti); usedD.add(p.di);
    matches.push([p.ti, p.di]);
}
// 3. Distance fallback for unmatched tracks (handles brand-new boxes).
for (let ti = 0; ti < tracks.length; ti++) {
    if (usedT.has(ti)) continue;
    let bestDi = -1, bestDist = TUNE.distMatchPx;
    for (let di = 0; di < dets.length; di++) {
        if (usedD.has(di)) continue;
        const d = Math.hypot(tracks[ti].foot.x - dets[di].foot.x, tracks[ti].foot.y - dets[di].foot.y);
        if (d < bestDist) { bestDist = d; bestDi = di; }
    }
    if (bestDi >= 0) { usedT.add(ti); usedD.add(bestDi); matches.push([ti, bestDi]); }
}

// 4. Update matched tracks (EMA smoothing, history append, occlusion flag).
const a = TUNE.posSmoothingAlpha;
for (const m of matches) {
    const t = tracks[m[0]], d = dets[m[1]];
    t.recoveredFromOcclusion = (t.framesSinceLastMatch || 0) >= 3;
    t.framesSinceLastMatch = 0;
    t.box.x = a*d.box.x + (1-a)*t.box.x;
    t.box.y = a*d.box.y + (1-a)*t.box.y;
    t.box.w = a*d.box.w + (1-a)*t.box.w;
    t.box.h = a*d.box.h + (1-a)*t.box.h;
    t.foot.x = a*d.foot.x + (1-a)*t.foot.x;
    t.foot.y = a*d.foot.y + (1-a)*t.foot.y;
    t.hits += 1;
    t.age = 0;
    const wasConfirmed = t.confirmed;
    if (t.hits >= TUNE.trackConfirmHits) t.confirmed = true;
    t.justConfirmed = !wasConfirmed && t.confirmed;
    t.insideHistory.push(inPoly({ x: t.foot.x, y: t.foot.y }, poly));
    if (t.insideHistory.length > 32) t.insideHistory.shift();
    t.posHistory.push({ x: t.foot.x, y: t.foot.y, frame });
    if (t.posHistory.length > 16) t.posHistory.shift();
}

// 5. Spawn new tracks with state inheritance from recently-died nearby tracks.
let nid = context.get('nextId') || 1;
const GRAVEYARD_PX = 100;
const GRAVEYARD_FRAMES = 30;
let graveyard = (context.get('graveyard') || []).filter(g => frame - g.diedFrame < GRAVEYARD_FRAMES);
for (let di = 0; di < dets.length; di++) {
    if (usedD.has(di)) continue;
    const d = dets[di];
    let inh = null, inhDist = GRAVEYARD_PX;
    for (const g of graveyard) {
        const gd = Math.hypot(g.foot.x - d.foot.x, g.foot.y - d.foot.y);
        if (gd < inhDist) { inhDist = gd; inh = g; }
    }
    const fInside = inPoly({ x: d.foot.x, y: d.foot.y }, poly);
    // Crossing inference from presence trail.
    let pendingEvent = null;
    if (!inh) {
        let foundOpposite = false, foundSame = false;
        for (const e of presenceTrail) {
            if (frame - e.frame < 1) continue;
            const tdx = e.x - d.foot.x;
            const tdy = e.y - d.foot.y;
            const parDist = Math.abs(tdx * lineDir.x + tdy * lineDir.y);
            if (parDist > TUNE.inferenceParallelMaxPx) continue;
            if (e.inside === fInside) foundSame = true;
            else foundOpposite = true;
        }
        if (foundOpposite && !foundSame) {
            pendingEvent = eventForArea(fInside);
        }
    }
    tracks.push({
        id: nid++,
        box: { x: d.box.x, y: d.box.y, w: d.box.w, h: d.box.h },
        foot: { x: d.foot.x, y: d.foot.y },
        hits: 1, age: 0, confirmed: false,
        insideHistory: [fInside],
        firstInside: fInside,
        posHistory: [{ x: d.foot.x, y: d.foot.y, frame }],
        lastCountFrame: inh ? inh.lastCountFrame : -999,
        lastEventType: inh ? inh.lastEventType : null,
        state: inh ? inh.state : null,
        lastStateChangeFrame: inh ? inh.lastStateChangeFrame : null,
        framesSinceLastMatch: 0,
        recoveredFromOcclusion: false,
        justConfirmed: false,
        pendingInferenceEvent: pendingEvent
    });
}
context.set('nextId', nid);

// 6. Age unmatched tracks; move expired ones to graveyard before removing.
for (let ti = 0; ti < tracks.length; ti++) {
    if (!usedT.has(ti)) {
        tracks[ti].age += 1;
        tracks[ti].framesSinceLastMatch = (tracks[ti].framesSinceLastMatch || 0) + 1;
    }
}
const dying = [];
const surviving = [];
for (const t of tracks) {
    if (t.age > TUNE.trackMaxAge) dying.push(t);
    else surviving.push(t);
}
for (const t of dying) {
    if (t.confirmed) {
        graveyard.push({
            foot: { x: t.foot.x, y: t.foot.y },
            state: t.state,
            lastStateChangeFrame: t.lastStateChangeFrame,
            lastEventType: t.lastEventType,
            lastCountFrame: t.lastCountFrame,
            diedFrame: frame
        });
    }
}
tracks = surviving;
context.set('graveyard', graveyard);
context.set('presenceTrail', presenceTrail);

// 7. Counting with hysteresis + perp-velocity gate + region cooldown.
let recentEvents = context.get('recentEvents') || [];
const events = [];
// State machine: immediate-transition with occlusion-aware validation.
const validateMotion = (t) => {
    if (t.recoveredFromOcclusion) return true;
    const k = TUNE.perpVelocityWindowFrames;
    if (t.posHistory.length < k) return true;
    const p0 = t.posHistory[t.posHistory.length - k];
    const p1 = t.posHistory[t.posHistory.length - 1];
    const perpComp = (p1.x - p0.x) * nrm.x + (p1.y - p0.y) * nrm.y;
    return Math.abs(perpComp) >= TUNE.perpVelocityMinPx;
};
for (const t of tracks) {
    if (!t.confirmed) continue;
    const H = t.insideHistory;
    if (!H.length) continue;
    const currentInside = H[H.length - 1];
    const currentStateName = currentInside ? 'inside' : 'outside';

    // Initial state adoption. Prefer spawn-time inference event from trail;
    // fall back to firstInside vs current check.
    if (t.state == null) {
        t.state = currentStateName;
        t.lastStateChangeFrame = frame;
        let inferredEvent = t.pendingInferenceEvent;
        if (!inferredEvent) {
            const initialStateName = t.firstInside ? 'inside' : 'outside';
            if (initialStateName !== currentStateName) {
                inferredEvent = eventForArea(currentInside);
            }
        }
        if (inferredEvent && validateMotion(t)) {
            t._pendingEvent = inferredEvent;
        }
        t.pendingInferenceEvent = null;
    } else if (t.state !== currentStateName) {
        if (frame - (t.lastStateChangeFrame || -999) < TUNE.minStateDwellFrames) continue;
        if (!validateMotion(t)) continue;
        t.state = currentStateName;
        t.lastStateChangeFrame = frame;
        t._pendingEvent = eventForArea(currentInside);
    }
    if (!t._pendingEvent) continue;
    const event = t._pendingEvent;
    t._pendingEvent = null;

    events.push({ type: event, track_id: t.id });
    t.lastCountFrame = frame;
    t.lastEventType = event;
}
context.set('tracks', tracks);
context.set('recentEvents', recentEvents);

// Status line: confirmed track count + inROI count.
let inRoi = 0, confirmedN = 0;
for (const t of tracks) {
    if (!t.confirmed) continue;
    confirmedN++;
    if (inPoly({ x: t.foot.x, y: t.foot.y }, poly)) inRoi++;
}
const statusText = 'tracks:' + confirmedN + ' inROI:' + inRoi + ' det:' + dets.length + ' ev:' + events.length;
node.status({ fill: events.length > 0 ? 'red' : (inRoi > 0 ? 'yellow' : 'green'), shape: 'dot', text: statusText });
flow.set('last_track_status', {
    frame,
    detections: dets.length,
    raw_boxes: Array.isArray(boxes) ? boxes.length : 0,
    tracks: tracks.length,
    confirmed: confirmedN,
    in_roi: inRoi,
    events: events.length,
    note: events.length ? 'event' : 'tracking',
    ts: now
});

if (events.length === 0) return null;
const deviceId = flow.get('device_id') || 'unknown';
const doorLabel = flow.get('door_label') || '?';
for (const e of events) {
    if (e.type === 'ENTRY') flow.set('event_entry_count', (flow.get('event_entry_count') || 0) + 1);
    if (e.type === 'EXIT') flow.set('event_exit_count', (flow.get('event_exit_count') || 0) + 1);
    flow.set('last_event', e.type + ' track=' + e.track_id + ' ts=' + now);
    node.warn('Publishing ' + e.type + ' to eagle/' + deviceId + '/event track=' + e.track_id);
    node.send({
        topic: 'eagle/' + deviceId + '/event',
        payload: JSON.stringify({ type: e.type, track_id: e.track_id, door: doorLabel, ts: now })
    });
}
return null;

const deviceId = flow.get('device_id') || 'unknown';
const doorLabel = flow.get('door_label') || '?';
const now = Date.now();
const track = flow.get('last_track_status') || {};
msg.topic = 'eagle/' + deviceId + '/heartbeat';
msg.payload = JSON.stringify({
    door: doorLabel,
    uptime_ms: now - (flow.get('start_time') || now),
    ts: now,
    system_ready: !!global.get('system_ready'),
    gate: flow.get('last_gate_status') || 'unknown',
    config_error: !!flow.get('config_error'),
    roi_error: !!flow.get('roi_error'),
    counts: {
        entries: flow.get('event_entry_count') || 0,
        exits: flow.get('event_exit_count') || 0,
        last_event: flow.get('last_event') || '-'
    },
    tracking: {
        frame: track.frame || 0,
        detections: track.detections || 0,
        tracks: track.tracks || 0,
        confirmed: track.confirmed || 0,
        in_roi: track.in_roi || 0,
        events: track.events || 0,
        note: track.note || '-'
    }
});
return msg;

// Runs beside Track + Count. Every camera publishes; ESP32 selects the inside ID.
const CONFIRM_MS = 2000;
const CLEAR_MS = 2000;
const MAX_FRAME_GAP_MS = 750;
const STALE_MS = 1000;
const PUBLISH_MS = 500;
const MIN_CONFIDENCE = 0.45;
const now = Date.now();
let s = context.get('presence') || {
    lastFrame: 0, candidateSince: null, clearSince: null,
    present: false, confirmedMs: 0, state: 'unknown', candidates: 0, blockers: 0,
    lastPublish: 0, configKey: ''
};
const cfg = global.get('roi_config');
const deviceId = flow.get('device_id') || 'unknown';
const ready = !!global.get('system_ready') && deviceId !== 'unknown' &&
    cfg && Array.isArray(cfg.polygon) && cfg.polygon.length >= 3;
function inPoly(pt, p) {
    let inside = false;
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
        const a = p[i], b = p[j];
        if (((a[1] > pt.y) !== (b[1] > pt.y)) &&
            pt.x < (b[0] - a[0]) * (pt.y - a[1]) / (b[1] - a[1]) + a[0]) inside = !inside;
    }
    return inside;
}
const configKey = ready ? JSON.stringify([cfg.polygon, cfg.masks, cfg.presence_polygon]) : '';
if (configKey !== s.configKey) {
    s = { lastFrame: 0, candidateSince: null, clearSince: null, present: false, confirmedMs: 0,
        state: 'unknown', candidates: 0, blockers: 0, lastPublish: 0, configKey };
}
const tick = msg.topic === '__presence_tick';
if (!tick && ready) {
    const data = msg.payload && (msg.payload.data || msg.payload);
    // A missing boxes array is invalid, NOT an empty detection frame.
    if (data && Array.isArray(data.boxes)) {
        const gap = s.lastFrame ? now - s.lastFrame : Infinity;
        if (gap > MAX_FRAME_GAP_MS) {
            s.candidateSince = null;
